const lessons=[{"sentences":[{"speaker":"A","text":"Welcome everyone to this short introductory lecture about practical memory techniques for everyday tasks.","position":1,"audioStartSeconds":0,"audioEndSeconds":6.602916666666666},{"speaker":"A","text":"Many people struggle to recall simple things although they have otherwise sharp minds.","position":2,"audioStartSeconds":6.8029166666666665,"audioEndSeconds":11.97125},{"speaker":"A","text":"We will explore several common methods today through hypothetical examples rather than strict science.","position":3,"audioStartSeconds":12.17125,"audioEndSeconds":18.627416666666665},{"speaker":"A","text":"Suppose you constantly forget where you put your keys when you arrive home.","position":4,"audioStartSeconds":18.827416666666668,"audioEndSeconds":23.324833333333334},{"speaker":"A","text":"A very simple habit is establishing a designated hook near the front door.","position":5,"audioStartSeconds":23.524833333333333,"audioEndSeconds":28.408875},{"speaker":"A","text":"Whenever you enter the house you place them there without exception.","position":6,"audioStartSeconds":28.608875,"audioEndSeconds":32.5135},{"speaker":"A","text":"Another common issue is remembering items you need to buy at the grocery store.","position":7,"audioStartSeconds":32.7135,"audioEndSeconds":37.481541666666665},{"speaker":"A","text":"Instead of writing a long list on paper you might visualize your kitchen table.","position":8,"audioStartSeconds":37.68154166666667,"audioEndSeconds":42.539791666666666},{"speaker":"A","text":"You then imagine placing a giant loaf of bread right on top of it.","position":9,"audioStartSeconds":42.73979166666667,"audioEndSeconds":46.94083333333333},{"speaker":"A","text":"Such unusual mental pictures make the items much harder to forget later.","position":10,"audioStartSeconds":47.14083333333333,"audioEndSeconds":52.153708333333334},{"speaker":"A","text":"People also forget important appointments because they rely entirely on their memory.","position":11,"audioStartSeconds":52.35370833333333,"audioEndSeconds":57.597791666666666},{"speaker":"A","text":"If you set an alarm on your phone you remove the stress completely.","position":12,"audioStartSeconds":57.79779166666667,"audioEndSeconds":61.85783333333333},{"speaker":"A","text":"Auditory reminders are extremely effective because they interrupt whatever you are doing.","position":13,"audioStartSeconds":62.057833333333335,"audioEndSeconds":67.367125},{"speaker":"A","text":"Some individuals prefer writing notes on small colored stickers.","position":14,"audioStartSeconds":67.567125,"audioEndSeconds":71.93566666666666},{"speaker":"A","text":"You can attach these sticky notes to your computer monitor before you sleep.","position":15,"audioStartSeconds":72.13566666666667,"audioEndSeconds":76.71041666666666},{"speaker":"A","text":"When morning arrives you see the bright message immediately upon waking up.","position":16,"audioStartSeconds":76.91041666666666,"audioEndSeconds":81.614},{"speaker":"A","text":"Try practicing just one of these methods starting tomorrow morning.","position":17,"audioStartSeconds":81.814,"audioEndSeconds":86.05370833333333},{"speaker":"A","text":"Thank you for your attention and good luck with your daily organization.","position":18,"audioStartSeconds":86.25370833333334,"audioEndSeconds":90.59445833333334}],"questions":[{"prompt":"Designated place for keys: ______","answer":"hook","evidenceSentence":5,"evidence":"designated hook","explanation":"Người nói đề xuất đặt chìa khóa lên một cái móc cố định gần cửa."},{"prompt":"Mental image location for groceries: ______ table","answer":"kitchen","evidenceSentence":8,"evidence":"kitchen table","explanation":"Ví dụ hình dung đồ vật trên bàn bếp thay vì viết giấy."},{"prompt":"Type of reminder using sound: ______ reminders","answer":"auditory","evidenceSentence":13,"evidence":"Auditory reminders","explanation":"Nhắc nhở bằng âm thanh giúp gián đoạn công việc hiện tại."},{"prompt":"Color of the stickers used for notes: ______","answer":"colored","evidenceSentence":14,"evidence":"colored stickers","explanation":"Giấy nhớ có màu sắc giúp thu hút sự chú ý."},{"prompt":"Object to attach notes to: computer ______","answer":"monitor","evidenceSentence":15,"evidence":"computer monitor","explanation":"Dán giấy nhắc việc lên màn hình máy tính."},{"prompt":"Time to try practicing: tomorrow ______","answer":"morning","evidenceSentence":17,"evidence":"tomorrow morning","explanation":"Khán giả được khuyến khích thử nghiệm phương pháp vào sáng ngày mai."}]}];const cards=[...document.querySelectorAll('article')];let stopping=null,stoppingAudio=null;
    document.addEventListener('play',event=>{if(event.target.tagName!=='AUDIO')return;document.querySelectorAll('audio').forEach(a=>{if(a!==event.target)a.pause()})},true);
    document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{let count=0;cards.forEach(c=>{c.hidden=button.dataset.filter!=='ALL'&&c.dataset.goal!==button.dataset.filter;if(!c.hidden)count++;else c.querySelector('audio').pause()});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.querySelector('#filter-status').textContent='Đang hiển thị '+count+' bài.'});
    const normal=value=>value.trim().toLowerCase().replace(/\s+/g,' ');
    document.querySelectorAll('[data-check]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.check);let score=0;lessons[i].questions.forEach((q,n)=>{const value=normal(document.getElementById('answer-'+i+'-'+n).value);if([q.answer,...(q.accepted||[])].some(a=>normal(a)===value))score++});document.getElementById('result-'+i).textContent=score+'/'+lessons[i].questions.length+' câu đúng. Mở phần đáp án để xem giải thích.'});
    document.querySelectorAll('[data-segment]').forEach(button=>button.onclick=async()=>{if(stopping)stopping();const [i,n]=button.dataset.segment.split(',').map(Number),audio=cards[i].querySelector('audio'),s=lessons[i].sentences[n];audio.currentTime=s.audioStartSeconds;const stop=()=>{stopping=null;stoppingAudio=null;audio.removeEventListener('timeupdate',check);audio.pause()},check=()=>{if(audio.currentTime>=s.audioEndSeconds)stop()};stopping=stop;stoppingAudio=audio;audio.addEventListener('timeupdate',check);try{await audio.play()}catch(_){stop();document.getElementById('result-'+i).textContent='Không phát được audio. Hãy dùng nút tải WAV để nghe.'}});
    document.querySelectorAll('audio').forEach(audio=>audio.addEventListener('pause',()=>{if(audio.paused&&stoppingAudio===audio&&stopping)stopping()}));
const authStatus=document.querySelector('#auth-status');
async function initializeAudio(){
 try{
  const response=await fetch('/api/auth/me',{credentials:'same-origin'});
  if(response.status===401){authStatus.hidden=false;authStatus.innerHTML='Đăng nhập để nghe audio. <a href="/login?next=%2Fcatalog%3Fgoal%3DALL">Đăng nhập</a> rồi mở bài từ thư viện bằng nút “Nghe toàn bài & làm câu hỏi”.';return}
  if(!response.ok)throw Error('account');
  document.querySelectorAll('audio').forEach(audio=>{audio.src=audio.dataset.src;audio.preload='none';audio.hidden=false});
  document.querySelectorAll('[data-segment]').forEach(button=>button.disabled=false);
  document.querySelectorAll('a[download]').forEach(link=>link.hidden=false);
 }catch(_){authStatus.hidden=false;authStatus.textContent='Không kiểm tra được đăng nhập. Hãy tải lại trang để thử lại.'}
}
initializeAudio();
